from decimal import Decimal, ROUND_HALF_UP


def backfill_approved_amounts(apps, schema_editor):
    ServiceRequest = apps.get_model('core', 'ServiceRequest')
    for item in ServiceRequest.objects.filter(completion_status='approved').iterator():
        works = list(item.works.all())
        base = sum((work.price for work in works), 0) if works else sum((service.approximate_price for service in item.subcategories.all()), 0)
        total = base + sum((extra.price for extra in item.extra_works.all()), 0)
        payout = (Decimal(total) * Decimal(40) / 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        ServiceRequest.objects.filter(pk=item.pk).update(approved_total=total, approved_payout=payout)


